/* ------------------------------------------------------------------ hooks */

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const sync = () => setReduced(mq.matches)
    sync()
    mq.addEventListener('change', sync)
    return () => mq.removeEventListener('change', sync)
  }, [])
  return reduced
}

// The escapement runs at the movement's real rate: five releases a second.
function useBeat(running) {
  const [beat, setBeat] = useState(0)
  useEffect(() => {
    if (!running) return undefined
    const id = window.setInterval(() => setBeat((b) => b + 1), 200)
    return () => window.clearInterval(id)
  }, [running])
  return beat
}

function useVisible(ref) {
  const [visible, setVisible] = useState(false)
  useEffect(() => {
    const node = ref.current
    if (!node) return undefined
    const io = new IntersectionObserver(([e]) => setVisible(e.isIntersecting), { threshold: 0.15 })
    io.observe(node)
    return () => io.disconnect()
  }, [ref])
  return visible
}

// Scroll progress across a section, measured against the top of the viewport
// so a reveal never resolves behind the reader.
function useScrollProgress(ref) {
  const [progress, setProgress] = useState(0)
  useEffect(() => {
    let frame = 0
    const measure = () => {
      frame = 0
      const node = ref.current
      if (!node) return
      const rect = node.getBoundingClientRect()
      const vh = window.innerHeight || 1
      const span = vh * 0.1 + rect.height
      const t = (vh * 0.7 - rect.top) / span
      setProgress(Math.min(1, Math.max(0, t)))
    }
    const onScroll = () => {
      if (!frame) frame = window.requestAnimationFrame(measure)
    }
    measure()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)
    return () => {
      window.cancelAnimationFrame(frame)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
    }
  }, [ref])
  return progress
}

function useReveal() {
  useEffect(() => {
    const nodes = Array.from(document.querySelectorAll('[data-reveal]'))
    if (!('IntersectionObserver' in window)) {
      nodes.forEach((n) => n.classList.add('is-in'))
      return undefined
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add('is-in')
            io.unobserve(e.target)
          }
        })
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.05 },
    )
    nodes.forEach((n) => io.observe(n))
    return () => io.disconnect()
  }, [])
}

/* ------------------------------------------------- the movement, in plan */

// Node geometry for the plan view. The path drawn between the nodes is the
// power path: the order is the order energy travels.
const NODES = {
  mainspring: { x: 130, y: 250 },
  barrel: { x: 182, y: 176 },
