function PowerPath() {
  const ref = useRef(null)
  const progress = useScrollProgress(ref)
  const visible = useVisible(ref)
  const reduced = usePrefersReducedMotion()
  const beat = useBeat(visible && !reduced)
  const [hovered, setHovered] = useState(null)
  const index = Math.min(POWER_PATH.length - 1, Math.floor(progress * POWER_PATH.length))
  const active = hovered || POWER_PATH[index].id

  return (
    <section className="section section-path" id="path" ref={ref}>
      <div className="section-head" data-reveal>
        <p className="eyebrow">01 — The power path</p>
        <h2>Six stages, in the order the energy travels</h2>
        <p className="section-lede">
          One wind puts 72 hours into a steel ribbon. Everything after it is a controlled way of
          giving that back, five times a second, without letting the rate drift.
        </p>
      </div>

      <div className="path-layout">
        <div className="path-figure">
          <div className="path-sticky">
            <MovementPlan active={active} pulse={progress} beat={beat} labelled={false} />
            <p className="path-readout">
              <span>{String(index + 1).padStart(2, '0')} / 06</span>
              <span>{POWER_PATH[index].name}</span>
            </p>
          </div>
        </div>

        <ol className="stages">
          {POWER_PATH.map((stage, i) => (
            <li
              key={stage.id}
              data-stage={stage.id}
              data-reveal
              className={`stage${active === stage.id ? ' is-live' : ''}`}
              onMouseEnter={() => setHovered(stage.id)}
              onMouseLeave={() => setHovered(null)}
            >
              <span className="stage-index">{String(i + 1).padStart(2, '0')}</span>
              <div className="stage-body">
                <h3>{stage.name}</h3>
                <p className="stage-figure">
                  <b>{stage.lead}</b>
                  <span>{stage.unit}</span>
                </p>
                <p className="stage-detail">{stage.detail}</p>
                <p className="stage-full">{stage.figure}.</p>
              </div>
            </li>
          ))}
        </ol>
      </div>

      <figure className="plate-figure" data-reveal>
        <img
          src="/media/horology-plate-xii-wellcome.jpg"
          alt="Coloured engraving, Horology Plate XII, showing a pocket watch mainspring, barrel, train, escapement and balance laid out as separate parts."
          loading="lazy"
          width="1000"
          height="1320"
        />
        <figcaption>
          The same six stages, laid out in 1810. <i>Clocks: mechanism of a pocket watch</i>, coloured
          engraving by J. Pass. Wellcome Collection, public domain. The order has not changed since;
          the tolerances have.
        </figcaption>
      </figure>
    </section>
  )
}

function Layers() {
  const [active, setActive] = useState(null)
  const total = LAYERS.reduce((sum, l) => sum + l.mm, 0)
  let offset = 0
  const stack = LAYERS.map((l) => {
    const item = { ...l, offset }
    offset += l.mm
    return item
  })

  return (
    <section className="section section-layers" id="layers">
      <div className="section-head" data-reveal>
        <p className="eyebrow">02 — Construction</p>
        <h2>Four layers, 3.8mm end to end</h2>
        <p className="section-lede">
          Front of the movement to back. The four thicknesses are the whole height of the caliber —
          there is nothing else in it.
        </p>
      </div>

      <div className="layers-layout">
        <div className="stack-wrap" data-reveal>
          <div className={`stack${active ? ' is-exploded' : ''}`}>
            {stack.map((l, i) => (
              <button
                type="button"
                key={l.id}
                data-layer={l.id}
                className={`plate plate-${l.id}${active === l.id ? ' is-active' : ''}${active && active !== l.id ? ' is-dim' : ''}`}
                style={{ '--i': i, '--mm': l.mm }}
                onMouseEnter={() => setActive(l.id)}
                onFocus={() => setActive(l.id)}
                onMouseLeave={() => setActive(null)}
                onBlur={() => setActive(null)}
                onClick={() => setActive((cur) => (cur === l.id ? null : l.id))}
                aria-pressed={active === l.id}
              >
                <span className="plate-face" aria-hidden="true" />
                <span className="sr-only">{l.name}, {l.thickness}</span>
              </button>
            ))}
          </div>
          <p className="stack-hint">Hover or tap a plate to lift it out of the stack.</p>
        </div>

        <div className="layers-side">
          <div className="elevation" aria-hidden="true">
            {stack.map((l) => (
              <div
                key={l.id}
                className={`band${active === l.id ? ' is-active' : ''}`}
                style={{ '--h': (l.mm / total) * 100 }}
              >
                <span>{l.thickness}</span>
              </div>
            ))}
            <p className="elevation-total">3.8mm</p>
          </div>

          <ol className="layer-list">
            {stack.map((l) => (
              <li
                key={l.id}
                data-reveal
                className={`layer${active === l.id ? ' is-active' : ''}`}
                onMouseEnter={() => setActive(l.id)}
                onMouseLeave={() => setActive(null)}
              >
                <h3>{l.name}</h3>
                <p className="layer-mm">{l.thickness}</p>
                <p className="layer-note">{l.note}</p>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  )
}

function Specification() {
