            {c.remaining} {c.name}
          </li>
        ))}
        <li><i className="tick" aria-hidden="true" />123 allocated</li>
      </ul>
    </div>
  )
}

function Reserve({ config, setConfig }) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
