        </div>

        <div className="reserve-card" data-reveal>
          {reserved ? (
            <div className="confirmation" role="status">
              <p className="confirm-mark" aria-hidden="true">Reserved</p>
              <p className="confirm-body">
                Reserved. {name}, we have held one {chosen.name} movement at CHF {chf(chosen.price)}{' '}
                and will write to {email}. {chosen.lead}.
              </p>
              <dl className="confirm-meta">
                <div><dt>Finish</dt><dd>{chosen.name}</dd></div>
                <div><dt>Price</dt><dd>CHF {chf(chosen.price)}</dd></div>
                <div><dt>Delivery</dt><dd>{chosen.lead}</dd></div>
              </dl>
              <p className="confirm-note">
                Not binding, and no payment has been taken.
              </p>
            </div>
          ) : (
            <form onSubmit={handleSubmit}>
              <p className="form-title">Reserve a movement</p>
              <div className="field">
                <label htmlFor="config">Which finish?</label>
                <select
                  id="config"
                  name="config"
                  required
                  value={config}
                  onChange={(e) => setConfig(e.target.value)}
                >
                  <option value="">Choose a finish</option>
                  {CONFIGURATIONS.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.name} — CHF {chf(c.price)}
                    </option>
                  ))}
                </select>
              </div>
              <div className="field">
                <label htmlFor="name">Your name</label>
                <input id="name" name="name" type="text" required value={name}
                  onChange={(e) => setName(e.target.value)} />
