              </div>

              <p className="form-summary">
                {chosen ? (
                  <>
                    <span>{chosen.name}</span>
                    <span>CHF {chf(chosen.price)}</span>
                    <span>{chosen.lead}</span>
                  </>
                ) : (
                  <span className="muted">No finish chosen yet.</span>
                )}
              </p>

              <button type="submit" className="btn btn-primary btn-wide">Reserve a movement</button>
            </form>
          )}
        </div>
      </div>
    </section>
  )
}

export default function App() {
