            >
              <span className="stage-index">{String(i + 1).padStart(2, '0')}</span>
              <div className="stage-body">
                <h3>{stage.name}</h3>
                <p className="stage-figure">
                  <b>{stage.lead}</b>
                  <span>{stage.unit}</span>
                </p>
                <p className="stage-detail">{stage.detail}</p>
                <p className="stage-full">{stage.figure}.</p>
