/* Aubry & Vent — Caliber 08
   Field: cool graphite (German silver, steel). Warm off-white type.
   Two accents, both taken off the movement: gilt for stored energy and
   figures, blued steel for anything you can touch. */

:root {
  --ink: #0b0d10;
  --ink-2: #111419;
  --ink-3: #171b21;
  --ink-4: #1e232a;
  --paper: #e9e3d6;
  --paper-2: #ded7c7;
  --paper-ink: #1a1712;
  --text: #e6dfd2;
  --text-2: #a9a79f;
  --muted: #7d8188;
  --gilt: #c9a24b;
  --gilt-soft: rgba(201, 162, 75, 0.16);
  --blue: #7c9fd6;
  --blue-deep: #3d5f96;
  --line: rgba(233, 224, 206, 0.13);
  --line-strong: rgba(233, 224, 206, 0.26);

  --ease-out: cubic-bezier(0.2, 0.8, 0.3, 1);
  --ease-in-out: cubic-bezier(0.6, 0, 0.3, 1);
  --t-fast: 120ms;
  --t-base: 200ms;
  --t-slow: 400ms;

  --sans: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif;
  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, monospace;

  --gutter: clamp(20px, 5vw, 64px);
  --max: 1240px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 88px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.04;
  margin: 0;
}

p {
  margin: 0;
}

img {
  max-width: 100%;
  display: block;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ------------------------------------------------------- ambient layer */

a,
button,
select,
input,
summary,
.finish,
.stage,
.layer,
.plate {
  transition: color var(--t-fast) var(--ease-out), background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out), box-shadow var(--t-base) var(--ease-out),
    opacity var(--t-base) var(--ease-out), transform var(--t-base) var(--ease-out);
}

:where(a, button, select, input):focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 3px;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity var(--t-slow) var(--ease-out), transform var(--t-slow) var(--ease-out);
}

[data-reveal].is-in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  ::before,
  ::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
  }
  [data-reveal] {
    opacity: 1;
    transform: none;
  }
}

/* -------------------------------------------------------------- shared */

.eyebrow {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gilt);
  margin-bottom: 20px;
}

.section {
  padding: clamp(72px, 11vw, 148px) var(--gutter);
  max-width: var(--max);
  margin: 0 auto;
  position: relative;
}

.section-head {
  max-width: 46rem;
}

.section-head h2 {
  font-size: clamp(2.2rem, 5vw, 3.6rem);
}

.section-lede {
  margin-top: 18px;
  max-width: 34rem;
  color: var(--text-2);
  font-size: 1.0625rem;
}

/* buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 14px 22px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  color: var(--text);
  background: transparent;
  cursor: pointer;
  min-height: 46px;
}

.btn:hover {
  border-color: var(--blue);
  color: #fff;
  background: rgba(124, 159, 214, 0.1);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--gilt);
  border-color: var(--gilt);
  color: #17140d;
  font-weight: 500;
}

.btn-primary:hover {
  background: #dcb45c;
  border-color: #dcb45c;
  color: #17140d;
}

.btn-small {
  padding: 9px 16px;
  min-height: 38px;
  font-size: 11px;
}

.btn-wide {
  width: 100%;
  margin-top: 22px;
}

/* ------------------------------------------------------------- topbar */

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px var(--gutter);
  background: rgba(11, 13, 16, 0.86);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}

.mark {
  display: flex;
  align-items: baseline;
  gap: 10px;
  text-decoration: none;
  color: var(--text);
  margin-right: auto;
}

.mark b {
  font-family: var(--serif);
  font-size: 1.15rem;
  font-weight: 400;
  letter-spacing: 0.01em;
}

.mark span {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.mark:hover span {
  color: var(--gilt);
}

.nav-links {
  display: flex;
  gap: 26px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  font-family: var(--mono);
  font-size: 11.5px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--text-2);
  text-decoration: none;
  padding-bottom: 3px;
  border-bottom: 1px solid transparent;
}

.nav-links a:hover {
  color: var(--text);
  border-bottom-color: var(--gilt);
}

/* --------------------------------------------------------------- hero */

.hero {
  padding: clamp(56px, 8vw, 104px) var(--gutter) clamp(48px, 7vw, 96px);
  max-width: var(--max);
  margin: 0 auto;
  border-bottom: 1px solid var(--line);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.92fr);
  gap: clamp(32px, 5vw, 72px);
  align-items: center;
}

.hero h1 {
  font-size: clamp(4rem, 12vw, 8.5rem);
  line-height: 0.88;
  display: flex;
  align-items: baseline;
  gap: 0.14em;
  flex-wrap: wrap;
}

.hero-num {
  font-family: var(--mono);
  font-size: 0.42em;
  font-weight: 300;
  letter-spacing: -0.02em;
  color: var(--gilt);
  border: 1px solid var(--gilt-soft);
  border-radius: 2px;
  padding: 0.12em 0.24em;
  align-self: center;
}

.hero-lede {
  margin-top: 28px;
  font-family: var(--serif);
  font-size: clamp(1.3rem, 2.3vw, 1.75rem);
  line-height: 1.28;
  max-width: 22ch;
}

.hero-body {
  margin-top: 20px;
  color: var(--text-2);
  max-width: 40ch;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 32px;
}

.hero-figures {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin: 48px 0 0;
  background: var(--line);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.hero-figures > div {
  background: var(--ink);
  padding: 16px 12px 18px;
}

.hero-figures dt {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.hero-figures dd {
  margin: 6px 0 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 1.5rem;
  color: var(--text);
}

.hero-figures dd span {
  font-size: 0.6em;
  color: var(--text-2);
  margin-left: 2px;
}

.hero-plan {
  margin: 0;
}

.hero-plan figcaption,
.plate-figure figcaption,
.workshop-figure figcaption {
  margin-top: 16px;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--muted);
  max-width: 40ch;
}

.hero-plan figcaption {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.beat-dot {
  flex: none;
  width: 7px;
  height: 7px;
  margin-top: 6px;
  border-radius: 50%;
  background: var(--muted);
}

.beat-dot.is-running {
  background: var(--gilt);
  animation: beat 400ms steps(1, end) infinite;
}

@keyframes beat {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0.28;
  }
}

/* ------------------------------------------------------- plan drawing */

.plan {
  width: 100%;
  height: auto;
  display: block;
  overflow: visible;
}

.plan-track {
  fill: none;
  stroke: rgba(233, 224, 206, 0.22);
  stroke-width: 1.25;
  stroke-dasharray: 3 5;
  stroke-linejoin: round;
}

.plan-wheel {
  fill: rgba(233, 224, 206, 0.035);
  stroke: rgba(233, 224, 206, 0.34);
  stroke-width: 1.1;
}

.plan-rim,
.plan-spoke,
.plan-tooth,
.plan-hands,
.plan-fork {
  fill: none;
  stroke: rgba(233, 224, 206, 0.3);
  stroke-width: 1;
  stroke-linecap: round;
}

.plan-spring {
  fill: none;
  stroke: rgba(201, 162, 75, 0.5);
  stroke-width: 1.1;
}

.plan-weight {
  fill: rgba(233, 224, 206, 0.4);
}

.plan-part {
  transition: opacity var(--t-base) var(--ease-out);
}

.plan-part.is-active .plan-wheel {
  stroke: var(--gilt);
  fill: rgba(201, 162, 75, 0.1);
}

.plan-part.is-active .plan-rim,
.plan-part.is-active .plan-spoke,
.plan-part.is-active .plan-tooth,
.plan-part.is-active .plan-hands,
.plan-part.is-active .plan-fork {
  stroke: rgba(201, 162, 75, 0.85);
}

.plan-part.is-active .plan-weight {
  fill: var(--gilt);
}

.plan-escape,
.plan-balance,
.plan-fork {
  transition: transform 170ms var(--ease-in-out);
}

.plan-pulse {
  fill: var(--gilt);
  filter: drop-shadow(0 0 9px rgba(201, 162, 75, 0.85));
}

.plan-labels line {
  stroke: rgba(233, 224, 206, 0.28);
  stroke-width: 1;
}

.plan-labels text {
  fill: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.06em;
}

/* --------------------------------------------------------- power path */

.section-path {
  padding-bottom: clamp(56px, 8vw, 96px);
}

.path-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: clamp(28px, 5vw, 72px);
  margin-top: clamp(40px, 6vw, 72px);
  align-items: start;
}

.path-sticky {
  position: sticky;
  top: 104px;
}

.path-readout {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 18px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.path-count {
  color: var(--gilt);
  font-variant-numeric: tabular-nums;
}

.path-name {
  color: var(--text-2);
}

.stages {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}

.stage {
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 8px;
  padding: 26px 16px 26px 0;
  border-bottom: 1px solid var(--line);
  position: relative;
}

.stage::before {
  content: '';
  position: absolute;
  left: -16px;
  top: -1px;
  bottom: -1px;
  width: 2px;
  background: var(--gilt);
  opacity: 0;
  transition: opacity var(--t-base) var(--ease-out);
}

.stage.is-live::before {
  opacity: 1;
}

.stage.is-live {
  background: linear-gradient(90deg, rgba(201, 162, 75, 0.07), transparent 62%);
}

.stage-index {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--muted);
  padding-top: 6px;
  font-variant-numeric: tabular-nums;
}

.stage.is-live .stage-index {
  color: var(--gilt);
}

.stage h3 {
  font-size: 1.5rem;
}

.stage-figure {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-top: 10px;
  flex-wrap: wrap;
}

.stage-figure b {
  font-family: var(--mono);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  font-size: clamp(1.75rem, 3.4vw, 2.5rem);
  line-height: 1;
  color: var(--text);
  letter-spacing: -0.02em;
}

.stage.is-live .stage-figure b {
  color: var(--gilt);
}

.stage-figure span {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.stage-detail {
  margin-top: 12px;
  color: var(--text-2);
  max-width: 46ch;
}

.stage-full {
  margin-top: 8px;
  font-size: 12px;
  color: var(--muted);
  font-family: var(--mono);
}

.plate-figure {
  margin: clamp(56px, 8vw, 104px) 0 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(24px, 5vw, 56px);
  align-items: end;
  padding-top: clamp(40px, 6vw, 64px);
  border-top: 1px solid var(--line);
}

.plate-figure img {
  width: 100%;
  height: auto;
  border: 1px solid var(--line);
  filter: saturate(0.92) brightness(0.96);
}

.plate-figure figcaption {
  max-width: 34ch;
  font-size: 13.5px;
  color: var(--text-2);
}

.plate-figure figcaption b {
  display: block;
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 400;
  color: var(--text);
  margin-bottom: 14px;
  line-height: 1.15;
}

/* ------------------------------------------------------------- layers */

.section-layers {
  border-top: 1px solid var(--line);
}

.layers-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(32px, 5vw, 72px);
  margin-top: clamp(40px, 6vw, 72px);
  align-items: start;
}

.stack-wrap {
  position: sticky;
  top: 104px;
}

.stack {
  --gap: 15px;
  position: relative;
  width: min(100%, 380px);
  aspect-ratio: 1;
  margin: 0 auto;
  perspective: 1200px;
  transform-style: preserve-3d;
  transform: rotateX(57deg) rotateZ(-32deg);
  transition: transform var(--t-slow) var(--ease-out);
}

.stack.is-exploded {
  --gap: 52px;
}

.plate {
  position: absolute;
  inset: 14%;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  transform-style: preserve-3d;
  transform: translateZ(calc((3 - var(--i)) * var(--gap)));
  transition: transform var(--t-slow) var(--ease-out), opacity var(--t-base) var(--ease-out);
}

.plate-face {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(233, 224, 206, 0.42);
  background: linear-gradient(145deg, rgba(233, 224, 206, 0.12), rgba(233, 224, 206, 0.03));
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.45);
}

.plate-dial-side .plate-face {
  border-radius: 50%;
  background-image: radial-gradient(rgba(233, 224, 206, 0.3) 0.6px, transparent 0.7px),
    linear-gradient(145deg, rgba(233, 224, 206, 0.1), rgba(233, 224, 206, 0.02));
  background-size: 9px 9px, auto;
}

.plate-main .plate-face {
  border-radius: 50%;
  background-image: repeating-conic-gradient(
      from 0deg,
      rgba(233, 224, 206, 0.09) 0deg 2deg,
      transparent 2deg 4deg
    ),
    linear-gradient(145deg, rgba(233, 224, 206, 0.14), rgba(233, 224, 206, 0.04));
}

.plate-bridge .plate-face {
  border-radius: 46% 46% 50% 50% / 50%;
  clip-path: polygon(4% 22%, 96% 6%, 100% 62%, 62% 100%, 10% 86%);
  background-image: repeating-linear-gradient(
      118deg,
      rgba(233, 224, 206, 0.14) 0 2px,
      transparent 2px 7px
    ),
    linear-gradient(145deg, rgba(233, 224, 206, 0.16), rgba(233, 224, 206, 0.05));
}

.plate-balance-cock .plate-face {
  clip-path: polygon(50% 0, 78% 12%, 88% 44%, 68% 72%, 30% 78%, 12% 46%, 22% 14%);
  border-radius: 40%;
  background-image: linear-gradient(145deg, rgba(201, 162, 75, 0.28), rgba(233, 224, 206, 0.06));
}

.plate-tag {
  position: absolute;
  right: -14%;
  top: 42%;
  transform: rotateZ(32deg) rotateX(-57deg);
  transform-origin: left center;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--muted);
  white-space: nowrap;
  opacity: 0;
  transition: opacity var(--t-base) var(--ease-out), color var(--t-base) var(--ease-out);
}

.stack.is-exploded .plate-tag {
  opacity: 1;
}

.plate.is-active .plate-tag {
  color: var(--gilt);
  opacity: 1;
}

.plate.is-active .plate-face {
  border-color: var(--gilt);
  box-shadow: 0 22px 44px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(201, 162, 75, 0.4);
}

.plate.is-dim {
  opacity: 0.4;
}

.plate:focus-visible {
  outline: none;
}

.plate:focus-visible .plate-face {
  border-color: var(--blue);
  box-shadow: 0 0 0 2px var(--blue);
}

.stack-hint {
  margin-top: 28px;
  text-align: center;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--muted);
}

.elevation {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 8px;
}

.elevation-total {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  color: var(--gilt);
  writing-mode: vertical-rl;
  height: 190px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-left: 1px solid var(--gilt);
  padding-left: 6px;
  margin: 0;
}

.elevation-bands {
  display: flex;
  flex-direction: column;
  gap: 4px;
  height: 190px;
  flex: 1;
}

.band {
  height: calc(var(--h) * 1%);
  min-height: 18px;
  border: 1px solid var(--line-strong);
  background: rgba(233, 224, 206, 0.05);
  display: flex;
  align-items: center;
  padding-left: 12px;
  transition: background-color var(--t-base) var(--ease-out), border-color var(--t-base) var(--ease-out);
}

.band span {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.band.is-active {
  background: rgba(201, 162, 75, 0.16);
  border-color: var(--gilt);
}

.band.is-active span {
  color: var(--gilt);
}

.layer-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.layer {
  padding: 22px 16px 22px 18px;
  border-bottom: 1px solid var(--line);
  border-left: 2px solid transparent;
}

.layer.is-active {
  border-left-color: var(--gilt);
  background: linear-gradient(90deg, rgba(201, 162, 75, 0.07), transparent 70%);
}

.layer h3 {
  font-size: 1.35rem;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}

.layer h3 em {
  font-family: var(--mono);
  font-style: normal;
  font-size: 0.75rem;
  letter-spacing: 0.06em;
  color: var(--gilt);
  font-variant-numeric: tabular-nums;
}

.layer-note {
  margin-top: 8px;
  color: var(--text-2);
  font-size: 0.95rem;
  max-width: 44ch;
}

/* ------------------------------------------------------ specification */

.section-spec {
  max-width: none;
  background: var(--paper);
  color: var(--paper-ink);
  padding-left: 0;
  padding-right: 0;
}

.spec-inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 0 var(--gutter);
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: clamp(32px, 5vw, 72px);
  align-items: start;
}

.section-spec .eyebrow {
  color: #8a6b1f;
}

.section-spec .section-lede {
  color: rgba(26, 23, 18, 0.68);
}

.specs {
  margin: 0;
  border-top: 1px solid rgba(26, 23, 18, 0.24);
}

.spec-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
  gap: 20px;
  padding: 13px 4px;
  border-bottom: 1px solid rgba(26, 23, 18, 0.15);
  align-items: baseline;
}

.spec-row:hover {
  background: rgba(26, 23, 18, 0.05);
}

.spec-row dt {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(26, 23, 18, 0.6);
}

.spec-row dd {
  margin: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 1.0625rem;
  color: var(--paper-ink);
}

/* ----------------------------------------------------------- finishes */

.finishes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  margin-top: clamp(36px, 5vw, 64px);
  background: var(--line);
  border: 1px solid var(--line);
}

.finish {
  background: var(--ink-2);
  padding: 32px 26px 28px;
  display: flex;
  flex-direction: column;
  border-top: 2px solid transparent;
}

.finish:hover {
  background: var(--ink-3);
}

.finish.is-chosen {
  border-top-color: var(--gilt);
  background: var(--ink-3);
}

.finish h3 {
  font-size: 1.6rem;
  min-height: 2.2em;
}

.finish-price {
  margin-top: 18px;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 2.1rem;
  letter-spacing: -0.02em;
  color: var(--text);
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.finish.is-chosen .finish-price {
  color: var(--gilt);
}

.finish-price .cur {
  font-size: 0.5em;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.finish-desc {
  margin-top: 16px;
  color: var(--text-2);
  font-size: 0.95rem;
  flex: 1;
}

.finish-meta {
  margin: 24px 0 24px;
  display: grid;
  gap: 12px;
  border-top: 1px solid var(--line);
  padding-top: 18px;
}

.finish-meta dt {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.finish-meta dd {
  margin: 4px 0 0;
  font-size: 0.95rem;
  color: var(--text);
}

.finish-meta dd span {
  color: var(--muted);
  font-size: 0.85em;
}

.btn-choose {
  width: 100%;
}

.btn-choose.is-chosen {
  border-color: var(--gilt);
  color: var(--gilt);
  background: var(--gilt-soft);
}

/* ----------------------------------------------------------- workshop */

.section-workshop {
  border-top: 1px solid var(--line);
}

.workshop-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1fr);
  gap: clamp(32px, 5vw, 80px);
  align-items: start;
}

.workshop-figure {
  margin: 0;
}

.workshop-figure img {
  width: 100%;
  height: auto;
  border: 1px solid var(--line);
  filter: contrast(1.04) saturate(0.85) brightness(0.9);
}

.run-figure {
  display: flex;
  align-items: baseline;
  gap: 20px;
  margin: 40px 0 8px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--line);
}

.run-figure b {
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(4.5rem, 11vw, 8rem);
  line-height: 0.8;
  color: var(--gilt);
  letter-spacing: -0.03em;
}

.run-figure span {
  color: var(--text-2);
  max-width: 18ch;
}

.atelier {
  margin: 0;
}

.atelier > div {
  display: grid;
  grid-template-columns: 110px minmax(0, 1fr);
  gap: 20px;
  padding: 20px 0;
  border-bottom: 1px solid var(--line);
}

.atelier dt {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gilt);
  padding-top: 4px;
}

.atelier dd {
  margin: 0;
  color: var(--text-2);
  max-width: 52ch;
}

/* ------------------------------------------------------------ reserve */

.section-reserve {
  border-top: 1px solid var(--line);
  padding-bottom: clamp(72px, 10vw, 132px);
}

.reserve-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.85fr);
  gap: clamp(32px, 5vw, 72px);
  align-items: start;
}

.allocation {
  margin-top: 40px;
}

.allocation-head {
  display: flex;
  align-items: baseline;
  gap: 14px;
  margin-bottom: 20px;
}

.allocation-head b {
  font-family: var(--mono);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  font-size: 2.6rem;
  color: var(--gilt);
  letter-spacing: -0.03em;
}

.allocation-head span {
  color: var(--text-2);
}

.ticks {
  display: grid;
  grid-template-columns: repeat(25, minmax(0, 1fr));
  gap: 4px;
  max-width: 460px;
}

.tick {
  display: block;
  height: 16px;
  background: rgba(233, 224, 206, 0.14);
  transition: background-color var(--t-base) var(--ease-out);
}

.tick.is-open {
  background: rgba(233, 224, 206, 0.45);
}

.tick.is-chosen {
  background: var(--gilt);
}

.allocation-key {
  list-style: none;
  margin: 22px 0 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
  font-size: 12.5px;
  color: var(--muted);
}

.allocation-key li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.allocation-key li.is-chosen {
  color: var(--gilt);
}

.allocation-key .tick {
  width: 4px;
  height: 13px;
}

.terms {
  margin-top: 36px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  color: var(--text-2);
  max-width: 44ch;
  font-size: 0.95rem;
}

.reserve-card {
  background: var(--ink-2);
  border: 1px solid var(--line-strong);
  padding: clamp(24px, 3vw, 36px);
}

.form-title {
  font-family: var(--serif);
  font-size: 1.75rem;
  margin-bottom: 24px;
}

.field {
  margin-bottom: 18px;
}

.field label {
  display: block;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 8px;
}

.field input,
.field select {
  width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  background: var(--ink);
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  font-family: var(--sans);
  font-size: 1rem;
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%),
    linear-gradient(135deg, var(--muted) 50%, transparent 50%);
  background-position: calc(100% - 20px) 21px, calc(100% - 14px) 21px;
  background-size: 6px 6px;
  background-repeat: no-repeat;
  cursor: pointer;
}

.field input:hover,
.field select:hover {
  border-color: var(--blue);
}

.field input:focus,
.field select:focus {
  border-color: var(--blue);
  outline: none;
  box-shadow: 0 0 0 1px var(--blue);
}

.form-summary {
  display: grid;
  gap: 4px;
  margin-top: 24px;
  padding: 16px 18px;
  border: 1px dashed var(--line-strong);
  min-height: 92px;
  align-content: center;
}

.sum-name {
  font-family: var(--serif);
  font-size: 1.25rem;
}

.sum-price {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  color: var(--gilt);
  font-size: 1.05rem;
}

.sum-lead,
.muted {
  font-size: 12.5px;
  color: var(--muted);
  font-family: var(--mono);
  letter-spacing: 0.04em;
}

.confirmation {
  display: grid;
  gap: 20px;
}

.confirm-mark {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gilt);
  border-bottom: 1px solid var(--gilt-soft);
  padding-bottom: 14px;
}

.confirm-body {
  font-family: var(--serif);
  font-size: 1.45rem;
  line-height: 1.28;
}

.confirm-meta {
  margin: 0;
  display: grid;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
}

.confirm-meta > div {
  background: var(--ink-2);
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: baseline;
}

.confirm-meta dt {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.confirm-meta dd {
  margin: 0;
  text-align: right;
  color: var(--text);
}

.confirm-note {
  font-size: 12.5px;
  color: var(--muted);
}

/* ------------------------------------------------------------- footer */

.footer {
  border-top: 1px solid var(--line);
  background: var(--ink-2);
}

.footer-inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 36px var(--gutter);
  display: flex;
  flex-wrap: wrap;
  gap: 20px 40px;
  align-items: center;
}

.footer-mark {
  font-family: var(--mono);
  font-size: 11.5px;
