import { chromium } from 'playwright'

const url = 'http://localhost:4173/'
const out = new URL('./shots/', import.meta.url).pathname.replace(/^\//, '')

const browser = await chromium.launch()

async function run(name, width, height, fn) {
  const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1 })
  const page = await ctx.newPage()
  const errors = []
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()))
  page.on('pageerror', (e) => errors.push(String(e)))
  await page.goto(url, { waitUntil: 'networkidle' })
  await page.waitForTimeout(600)
  if (fn) await fn(page)
  console.log(name, 'errors:', errors.length ? errors : 'none')
  await ctx.close()
}

async function shotFull(page, file) {
  // walk the page so reveals fire
  const h = await page.evaluate(() => document.body.scrollHeight)
  for (let y = 0; y < h; y += 400) {
    await page.evaluate((v) => window.scrollTo(0, v), y)
    await page.waitForTimeout(70)
  }
  await page.evaluate(() => window.scrollTo(0, 0))
  await page.waitForTimeout(400)
  await page.screenshot({ path: file, fullPage: true })
}

await run('desktop', 1440, 900, async (page) => {
  await shotFull(page, `${out}desktop-full.png`)
})

await run('mobile', 390, 844, async (page) => {
  await shotFull(page, `${out}mobile-full.png`)
})

await browser.close()

